{
  "findings": [
    {
      "check_id": "CKV_AZURE_10",
      "title": "PostgreSQL server log retention is too short",
      "resource": "azurerm_postgresql_configuration.negative1",
      "severity": "MEDIUM",
      "explanation": "The 'log_retention_days' configuration is set to 5 days, which is below the recommended minimum of 7 days for effective security auditing and incident response."
    }
  ],
  "patched_code": "resource \"azurerm_postgresql_configuration\" \"negative1\" {\n  name                = \"log_retention_days\"\n  resource_group_name = azurerm_resource_group.example.name\n  server_name         = azurerm_postgresql_server.example.name\n  value               = 7\n}",
  "fix_summary": "Increased the PostgreSQL log retention period from 5 days to 7 days to meet security best practices for audit logging."
}
